function load$GridVoucherDetail$(g) {
	g.add_itemValueChanged(onChange$GridVoucherDetail$);
	g.add_onResponseComplete(on$GridVoucherDetail$ResponseComplete);
	g.add_commandEvent(on$GridVoucherDetail$ExecuteCommand);
	&FormulaExpression;
	&ESG.LoadScriptHoverField;
	g.$h = [['voucherCode', 'String', g._voucherCode], 'ma_kh', 'ngay_lct', 'ma_tt', 'ma_nt', 'ma_dvcs', 'stt_rec'];
	udf$Detail$(g);
	&VoucherGoodsTypeGridDetailLoadScript;
}
function scatter$GridVoucherDetail$(g) {
	var f = g.get_element().parentForm;
	if (f._action != 'View') {
		for (var r = 1; r <= g._rowCount; r++) {
			g._getItem(r, g._getColumnOrder('px_gia_dd')).disabled = (g._getItem(r, g._getColumnOrder('loai')).value != '');
		}
	}
	g.executeAggregate([g.$a.t_tien_giam_nt, g.$a.t_tien_giam, g.$a.t_tien_phi_nt, g.$a.t_tien_phi]);
}
function dispose$GridVoucherDetail$(g) {
	g.$a = null;
	try {g.remove_commandEvent(on$GridVoucherDetail$ExecuteCommand);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridVoucherDetail$ResponseComplete);} catch (ex) {}
	try {g.remove_itemValueChanged(onChange$GridVoucherDetail$);} catch (ex) {}
}
function onChange$GridVoucherDetail$GoodsType(o) {o.grid.request(o, 'GoodsType', 'GoodsType', ['loai'], null, false);}
function onChange$GridVoucherDetail$Item(o) {o.grid.request(o, 'Item', 'Item', ['ma_vt', 'ma_kho', 'ma_vi_tri', 'so_luong', 'tk_dt', 'tk_gv', 'tk_ck', 'tk_cpbh', ['action', 'Decimal', o.grid.get_element().parentForm._action == 'Edit' ? 1 : 0]], o.grid.$h, true);}
function onChange$GridVoucherDetail$UOM(o) {o.grid.request(o, 'UOM', 'UOM', ['ma_vt', 'ma_kho', 'ma_vi_tri', 'ma_lo', 'dvt', 'so_luong', ['action', 'Decimal', o.grid.get_element().parentForm._action == 'Edit' ? 1 : 0]], o.grid.$h, true);}
function onChange$GridVoucherDetail$Site(o) {o.grid.request(o, 'Site', 'Site', ['ma_vt', 'ma_kho', 'ma_lo', 'dvt', 'so_luong', 'he_so', ['action', 'Decimal', o.grid.get_element().parentForm._action == 'Edit' ? 1 : 0]], o.grid.$h, true);}
function onChange$GridVoucherDetail$Quantity(o) {o.grid.request(o, 'Quantity', 'Quantity', ['ma_vt', 'ma_kho', 'dvt', 'so_luong', 'he_so'], o.grid.$h);}
function onChange$GridVoucherDetail$Promotion(o) {
	var g = o.grid, row = o.row, item = g._getItem(row, g._getColumnOrder('ma_vt')), v = g._getItemValue(row, g._getColumnOrder('km_yn'));
	if (&DetailTaxPromotionValidConditional;(!item._saleAccount) || (!item._COSGAccount) || (!item._promotionAccount)) g.request(o, 'Promotion', 'Promotion', ['ma_vt']);
	if (v == '0') {
		g.setItemGridBehavior(o, [['tk_dt', item._saleAccount, ['', item._saleType], null], ['tk_gv', item._COSGAccount, ['', item._COSGType], null], ['tk_cpbh', '', '', null]]);
	} else {
		g.setItemGridBehavior(o, [['tk_dt', item._promotionAccount, ['', item._promotionType], null], ['tk_gv', item._promotionAccount, ['', item._promotionType], null]]);
		if (v == '1') g.setItemGridBehavior(o, [['tk_cpbh', '', '', null]]);
			else g.setItemGridBehavior(o, [['tk_cpbh', item._promotionAccount, ['', item._promotionType], null]]);
	}
	&DetailTaxPromotionValid;
}
function onChange$GridVoucherDetail$Discount(o) {
	var g = o.grid, row = o.row, item = g._getItem(row, g._getColumnOrder('ma_vt'));
	if (!g._getItemValue(row, g._getColumnOrder('ck_nt'))) g.setItemGridBehavior(o, [['tk_ck', '', '', null]]);
	else {
		if (!item._discountAccount) g.request(o, 'Discount', 'Discount', ['ma_vt', 'tk_ck']);
			else g.setItemGridBehavior(o, [['tk_ck', [item._discountAccount, '[ck_nt] > 0'], ['', item._discountType], true]]);
	}
}
function onChange$GridVoucherDetail$(sender, eventArgs) {
	var o = eventArgs.get_object(), g = o.grid, f = g.get_element().parentForm, name = o.field.Name;
	switch (name) {
		case 'km_yn':
			&VoucherGoodsTypePromotionChange;
			onChange$GridVoucherDetail$Promotion(o);
			g.executeAggregate([g.$a.t_tien_nt2, g.$a.t_tien2, g.$a.t_km_nt, g.$a.t_km, g.$a.t_km_ct_nt, g.$a.t_km_ct]);
			on$GridVoucherDetail$TaxChange(o, g, f);
			on$GridVoucherDetail$PromotionChange(o, g, f);
			break;
		case 'gia_nt2':
			g.executeExpression(o, [g.$a.gia2, g.$a.tien_nt2, g.$a.AmountFormula, g.$a.ck_nt, g.$a.ck_tl]);
			on$GridVoucherDetail$AmountChange(o, g, f);
			on$GridVoucherDetail$TaxChange(o, g, f);
			onChange$GridVoucherDetail$Discount(o);
			g.live(o, 'tien_nt2');
			break;
		case 'gia2':
			&DetailTaxValidSalesPrice;
			break;
		case 'tien_nt2':
			if (f._calPrice) g.validExpression(o, [g.$a.gia_nt2_sl, g.$a.gia2]);
			g.executeExpression(o, [g.$a.tien2_tg, g.$a.ck_nt, g.$a.ck_tl]);
			on$GridVoucherDetail$AmountChange(o, g, f);
			on$GridVoucherDetail$TaxChange(o, g, f);
			onChange$GridVoucherDetail$Discount(o);
			g.live(o, 'ck_nt');
			break;
		case 'tien2':
			if (f._calPrice) g.validExpression(o, [g.$a.gia2_sl]);
			&DetailTaxValidSalesAmount;
			break;
		case 'tl_ck':
			g.validExpression(o, [g.$a.ck_nt, g.$a.ck_tl], [g.$a.t_tien_nt2, g.$a.t_tien2, g.$a.t_ck_nt, g.$a.t_ck], null, 'ck_nt');
			on$GridVoucherDetail$TaxChange(o, g, f);
			onChange$GridVoucherDetail$Discount(o);
			break;
		case 'ck_nt':
			g.validExpression(o, [g.$a.ck_tg], [g.$a.t_tien_nt2, g.$a.t_tien2, g.$a.t_ck_nt, g.$a.t_ck]);
			on$GridVoucherDetail$TaxChange(o, g, f);
			onChange$GridVoucherDetail$Discount(o);
			break;
		case 'ck':
			&DetailTaxValidDiscount;
			break;
		case 'gia_nt':
			g.validExpression(o, [g.$a.gia, g.$a.tien_nt, g.$a.tien_sl], [g.$a.t_tien_nt, g.$a.t_tien], null, 'tien_nt');
			break;
		case 'gia':
			g.validExpression(o, [g.$a.tien_sl], [g.$a.t_tien], null, 'tien');
			break;
		case 'tien_nt':
			if (f._calPrice) g.validExpression(o, [g.$a.gia_nt_sl, g.$a.gia]);
			g.validExpression(o, [g.$a.tien_tg], [g.$a.t_tien_nt, g.$a.t_tien]);
			break;
		case 'tien':
			if (f._calPrice) g.validExpression(o, [g.$a.gia_sl]);
			g.executeAggregate([g.$a.t_tien]);
			break;
		&DetailTaxOnchange;
		&EnvironmentTaxDetailChange;
		default:
			break;
	}
}
function on$GridVoucherDetail$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm;
	switch (action) {&ScriptCheckGridAction;
		&Clipboard.Event.Before;
		&Clipboard.Event.Before.Request;
		&Clipboard.Event.Before.Process;
		&Clipboard.Event.After;
		&Clipboard.Event.After.Process;
		case 'AfterRemoveRow':
			on$GridVoucherDetail$RowChange(g, f);
			break;
		case 'AfterInsertRow':
			&VoucherGoodsTypeGridExecuteCommand;
			break;
		case 'AfterCloneRow':
			g.setItemFieldValue('stt_rec0', e.type.Value, '');
			&VoucherGoodsTypeGridExecuteCommand;
			on$GridVoucherDetail$RowChange(g, f);
			break;
		case 'Check':
			&ESG.ScriptCheck;
			if (!(g.validRowExpression('so_luong', '([gia_ton] != 3) || ([gia_ton] == 3 && [so_luong] != 0)'))) break;
			if (g._tracked$Lot && !(g.validRowExpression('ma_lo', '(![lo_yn]) || ([ma_lo] != "")'))) break;
			if (g._tracked$Location && !(g.validRowExpression('ma_vi_tri', '(![vi_tri_yn]) || ([ma_vi_tri] != "")'))) break;
			if (!(g.validRowExpression('tk_cpbh', '([km_yn] == 0) || ([km_yn] == 1) || ([tk_cpbh] != "")'))) break;
			&EnvironmentTaxCheckPromotion;
			&EnvironmentTaxCheck;
			&DetailTaxExecuteCommandCheck;
			break;
		&GridExtraToolbarExecuteCommandScript;
		case 'Lookup':
			var r = g._activeRow, c = true, a = ['vt', 'kho', 'vi_tri', 'lo'];
			if (f._action == 'View' || r == -1 || !r || !(g._getItemValue(r, g._getColumnOrder('px_gia_dd')))) break;
			for (var i = 0; i < a.length; i++) {
				var v1 = g._getItem(r, g._getColumnOrder('ma_' + a[i])), v2 = g._getItem(r, g._getColumnOrder('ten_' + a[i] + '%l'));
				if ((v1.addControl || v1.label) && !v2.checked) {
					c = false;
					break;
				}
			}
			if (!c || !f.validFields('ngay_lct')) break;
			if (g._getItemValue(r, g._getColumnOrder('ma_vt')) != '') {
				g._siteCode = g._getItemValue(r, g._getColumnOrder('ma_kho'));
				if (!g._onchangeForeignCurrencyPriceExpression) g._onchangeForeignCurrencyPriceExpression = [g.$a.gia, g.$a.tien_nt, g.$a.tien_sl];
				g.showForm('ViewReceiptFilter');
			}
			break;
		case 'Retrieve':
			if (f._action == 'View') break;
			if (!f.validFields('ma_kh, ngay_lct')) break;
			switch (e.type.Value) {
				case '0':
				case '10':
					g.showForm('SVOrderFilter');
					break;
				case '30':
					if (f.getItemValue('loai_ct') != '2') g.showForm('SVIssueFilter');
					break;
				default:
					break;
			}
			break;
		case 'Copying':
			set$Voucher$EmptyExternalField(g, 'dh_so, dh_ln, px_so, px_ln, stt_rec_dh, stt_rec0dh, stt_rec_px, stt_rec0px, stt_rec_pn, stt_rec0pn');
			break;
		default:
			break;
	}
}

function on$GridVoucherDetail$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
		case 'Item':
			var v = (result[0].Value == '' ? true : null), t = (result[0].Value == '' ? 'false' : 'true'), p = $func.trim(result[15].Value);
			o._promotionAccount = (p == '' ? null : p);
			o._promotionType = (result[16].Value == '0' ? false : true);
			o._saleAccount = (result[9].Value == '' ? null : result[9].Value);
			o._saleType = (result[10].Value == '0' ? false : true);
			o._COSGAccount = (result[11].Value == '' ? null : result[11].Value);
			o._COSGType = (result[12].Value == '0' ? false : true);
			g.setItemGridBehavior(o, [
				['ma_kho', result[0].Value, '', true],
				['ma_vi_tri', result[1].Value, '', v],
				['ma_lo', result[2].Value, '', null],
				['dvt', result[3].Value, '', true],
				['he_so', result[4].Value, null, null],
				['gia_ban_nt', result[5].Value, null, null],
				['gia_nt2', result[6].Value, null, true],
				['ck_nt', result[7].Value, null, true],
				['tk_vt', result[8].Value, '', true],
				['tk_dt', [result[9].Value, '[km_yn] == "0"'], ['', result[10].Value], true],
				['tk_gv', [result[11].Value, '[km_yn] == "0"'], ['', result[12].Value], true],
				['tk_ck', [result[13].Value, '[ck_nt] > 0'], ['', result[14].Value], true],
				['tk_cpbh', [result[15].Value, '(([km_yn] == 2) || ([km_yn] == 3))'], ['', result[16].Value], true],
				['gia_ton', result[17].Value, null, null],
				['vi_tri_yn', [result[18].Value, t], null, null],
				['lo_yn', result[19].Value, null, null],
				['ton13', result[22].Value, null, null]&EnvironmentTaxDetailResponseItem;
			]);
			&DetailTaxResponseCompleteItem;
			onChange$GridVoucherDetail$Promotion(o);
			on$GridVoucherDetail$SalesPriceChange(o, g, f, (result[7].Value > 0));
			o._discountAccount = result[13].Value;
			o._discountType = result[14].Value;
			&EnvironmentTaxDetailResponseValid;
			&VoucherGoodsTypeResponseChange;
			g.live(o, 'dvt');
			break;
		case 'UOM':
			on$GridVoucherDetail$SalesPriceResponse(result, o, g, f, true);
			g.setItemGridBehavior(o, [['ton13', result[4].Value, null, null]&EnvironmentTaxDetailResponseUOM;]);
			&EnvironmentTaxDetailResponseValid;
			break;
		case 'Site':
			&EIEditReferenceSiteResponse;
			g.setItemGridBehavior(o, [
				['tk_vt', result[4].Value, '', true],
				['ma_vi_tri', '', '', null],
				['vi_tri_yn', result[5].Value, null, null],
				['ton13', result[6].Value, null, null]
			]);
			break;
		case 'Location':
		case 'Lot':
			g.setItemGridBehavior(o, [['ton13', result[0].Value, null, null]]);
			break;
		case 'Quantity':
			on$GridVoucherDetail$SalesPriceResponse(result, o, g, f);
			g.validExpression(o, [g.$a.tien_nt, g.$a.tien_sl&EnvironmentTaxDetailChangeQuatity;], [g.$a.t_so_luong, g.$a.t_tien_nt, g.$a.t_tien&EnvironmentTaxDetailChangeQuatityTotal;], null, 'gia_nt2');
			&EnvironmentTaxDetailResponseQuantity;
			onChange$GridVoucherDetail$Discount(o);
			break;
		case 'Promotion':
			var p = $func.trim(result[0].Value), item = g._getItem(o.row, g._getColumnOrder('ma_vt')), v = g._getItemValue(o.row, g._getColumnOrder('km_yn'));
			item._promotionAccount = (p == '' ? null : p);
			item._promotionType = (result[1].Value == '0' ? false : true);
			item._saleAccount = (result[2].Value == '' ? null : result[1].Value);
			item._saleType = (result[3].Value == '0' ? false : true);
			item._COSGAccount = (result[4].Value == '' ? null : result[3].Value);
			item._COSGType = (result[5].Value == '0' ? false : true);
			if (v == '0') {
				g.setItemGridBehavior(o, [
					['tk_dt', result[2].Value, ['', item._saleType], null],
					['tk_gv', result[4].Value, ['', item._COSGType], null],
					['tk_cpbh', '', '', null]
				]);
			} else {
				g.setItemGridBehavior(o, [['tk_dt', p, ['', item._promotionType], null],['tk_gv', p, ['', item._promotionType], null]]);
				if (v == '1') g.setItemGridBehavior(o, [['tk_cpbh', '', '', null]]);
					else g.setItemGridBehavior(o, [['tk_cpbh', item._promotionAccount, ['', item._promotionType], null]]);
			}
			&DetailTaxPromotionValidResponse;
			&DetailTaxPromotionValid;
			break;
		case 'Discount':
			var item = g._getItem(o.row, g._getColumnOrder('ma_vt'));
			g.setItemGridBehavior(o, [['tk_ck', [result[0].Value, '[ck_nt] > 0'], ['', result[1].Value], true]]);
			item._discountAccount = result[0].Value;
			item._discountType = result[1].Value;
			break;
		case 'GetMemoByOrderKey':
			if (!f.getItemValue('dien_giai')) f.setItemValue('dien_giai', result[0].Value);
			break;
		&DetailTaxResponseComplete;
		&VoucherGoodsTypeResponseComplete;
		&ESG.ScriptGridResponse;
		default:
			break;
	}
}
