function on$GridVoucherDetail$SalesPriceResponse(result, o, g, f, force) {
	var a = [['gia_nt2', result[2].Value, null, true], ['ck_nt', result[3].Value, null, true]], v = true;
	if (force) {
		v = false;
		Array.add(a, ['he_so', result[0].Value, null, true]);
		Array.add(a, ['gia_ban_nt', result[1].Value, null, true]);
	}
	g.setItemGridBehavior(o, a);
	on$GridVoucherDetail$SalesPriceChange(o, g, f, (result[3].Value > 0), v);
}
function on$GridVoucherDetail$SalesPriceChange(o, g, f, d, force) {
	if (d) g.executeExpression(o, ['[tl_ck]:=0']);
	if (force) g.executeExpression(o, [g.$a.gia2, g.$a.ck_tg, g.$a.tien_nt2, g.$a.AmountFormula]);
		else g.executeExpression(o, [g.$a.gia_ban, g.$a.gia2, g.$a.ck_tg, g.$a.tien_nt2, g.$a.AmountFormula]);
	if (!d) g.executeExpression(o, [g.$a.ck_nt, g.$a.ck_tl], '[tl_ck] != 0');
	on$GridVoucherDetail$AmountChange(o, g, f);
	on$GridVoucherDetail$TaxChange(o, g, f);
}
function getMemoByOrderKey(g, v) {if (g._getMemoByOrderKey == 1) g.request(g, 'GetMemoByOrderKey', 'GetMemoByOrderKey', [['stt_rec', 'String', v]]);}
