	&VoucherGoodsTypeValidRowChange;
	g.executeAggregate([g.$a.t_tien_nt2, g.$a.t_tien2, g.$a.t_tc_tien_nt2, g.$a.t_tc_tien2, g.$a.t_ck_nt, g.$a.t_ck, g.$a.t_km_nt, g.$a.t_km, g.$a.t_km_ct_nt, g.$a.t_km_ct]);
	on$GridVoucherDetail$PromotionChange(o, g, f);
}
